-- ---------------------------------------------------------------------------
-- Table: contenido_imagenes (supabase/schemas/26_contenido_imagenes.sql)
-- ---------------------------------------------------------------------------

create table public.contenido_imagenes (
  id           uuid        not null default gen_random_uuid() primary key,
  contenido_id uuid        not null references public.contenidos (id) on delete cascade,
  path         text        not null,
  orden        integer     not null,
  created_at   timestamptz not null default now(),
  unique (contenido_id, orden)
);

comment on table public.contenido_imagenes is 'Imágenes ordenadas de un contenido tipo galería (cma / ic). Un contenido de video/audio/egregor nunca tiene filas acá.';

-- ---------------------------------------------------------------------------
-- Function: is_console_user (supabase/schemas/25_admin_functions.sql)
-- ---------------------------------------------------------------------------

create or replace function public.is_console_user(p_user_id uuid default auth.uid())
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1
      from public.profiles p
      join public.roles    r on r.id = p.rol_id
     where p.id      = p_user_id
       and r.codigo  in ('admin', 'terapeuta')
  );
$$;

comment on function public.is_console_user is
  'Devuelve true si el usuario (default = auth.uid()) tiene rol "admin" o "terapeuta" — es decir, es un usuario de consola, no un paciente. rol_id null (pacientes) falla el join y devuelve false. Usada en la policy de lectura de contenido_imagenes.';

-- ---------------------------------------------------------------------------
-- Function: create_contenido (altered — supabase/schemas/72_rpcs_contenidos.sql)
-- ---------------------------------------------------------------------------

create or replace function public.create_contenido(
  p_tipo         text,
  p_titulo       text,
  p_descripcion  text,
  p_recurso_ref  text,
  p_duracion_seg integer
)
returns table(
  id           uuid,
  tipo         text,
  titulo       text,
  descripcion  text,
  recurso_ref  text,
  duracion_seg integer
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'no_autorizado' using errcode = '42501';
  end if;

  if p_tipo not in ('video', 'audio', 'egregor', 'cma', 'ic') then
    raise exception 'tipo_invalido' using errcode = '23514';
  end if;

  if p_titulo is null or btrim(p_titulo) = '' then
    raise exception 'titulo_vacio' using errcode = '23514';
  end if;

  -- Guard sin excepción por tipo, a propósito: las filas cma/ic se crean
  -- exclusivamente via create_contenido_galeria, que es atómica sobre
  -- contenidos + contenido_imagenes en una sola transacción (design §3
  -- ADR-3). Este guard es lo que hace estructuralmente imposible una
  -- galería con cero imágenes a través de create_contenido — eximir cma/ic
  -- acá permitiría insertar un contenidos con tipo='cma' y ninguna fila en
  -- contenido_imagenes, asignable igual a un slot del plan (el guard tipo-
  -- por-orden de set_entregas_plan solo compara c.tipo, no exige imágenes) y
  -- expuesta al paciente como un carrusel vacío sin error en ningún punto.
  if p_recurso_ref is null or btrim(p_recurso_ref) = '' then
    raise exception 'recurso_ref_vacio' using errcode = '23514';
  end if;

  return query
    insert into public.contenidos (tipo, titulo, descripcion, recurso_ref, duracion_seg, activo)
    values (p_tipo, btrim(p_titulo), p_descripcion, btrim(p_recurso_ref), p_duracion_seg, true)
    returning
      contenidos.id,
      contenidos.tipo,
      contenidos.titulo,
      contenidos.descripcion,
      contenidos.recurso_ref,
      contenidos.duracion_seg;
end;
$$;

comment on function public.create_contenido(text, text, text, text, integer) is
  'Inserta un nuevo contenido (video/audio/egregor/cma/ic) persistiendo recurso_ref y duracion_seg. Valida is_admin(), tipo válido (5 valores), título no vacío y recurso_ref no vacío para TODOS los tipos, sin excepción. cma/ic NO se crean vía este RPC: create_contenido_galeria es el único flujo para galerías (atómico sobre contenidos + contenido_imagenes); este guard sin excepción es lo que hace estructuralmente imposible una galería con cero imágenes. p_duracion_seg es nullable (se acepta null cuando el navegador no expone la duración). Set-returning: devuelve la fila creada para que el hook la mapee.';

-- ---------------------------------------------------------------------------
-- Function: create_contenido_galeria (new — supabase/schemas/72_rpcs_contenidos.sql)
-- ---------------------------------------------------------------------------

create or replace function public.create_contenido_galeria(
  p_tipo        text,
  p_titulo      text,
  p_descripcion text,
  p_paths       text[]
)
returns table(
  id          uuid,
  tipo        text,
  titulo      text,
  descripcion text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    raise exception 'no_autorizado' using errcode = '42501';
  end if;

  if p_tipo not in ('cma', 'ic') then
    raise exception 'tipo_invalido' using errcode = '23514';
  end if;

  if p_titulo is null or btrim(p_titulo) = '' then
    raise exception 'titulo_vacio' using errcode = '23514';
  end if;

  if p_paths is null or array_length(p_paths, 1) is null then
    raise exception 'galeria_vacia' using errcode = '23514';
  end if;

  insert into public.contenidos (tipo, titulo, descripcion, recurso_ref, duracion_seg, activo)
  values (p_tipo, btrim(p_titulo), p_descripcion, null, null, true)
  returning contenidos.id into v_id;

  insert into public.contenido_imagenes (contenido_id, path, orden)
  select v_id, p.path, p.ord
    from unnest(p_paths) with ordinality as p(path, ord);

  return query
    select
      c.id,
      c.tipo,
      c.titulo,
      c.descripcion
      from public.contenidos as c
     where c.id = v_id;
end;
$$;

comment on function public.create_contenido_galeria(text, text, text, text[]) is
  'Crea una galería (cma/ic) en una sola transacción: inserta la fila contenidos (recurso_ref/duracion_seg null) y sus contenido_imagenes en orden de subida (with ordinality — el cliente nunca envía orden). Valida is_admin(), tipo in (cma, ic), título no vacío y p_paths no vacío. Atómico a propósito (design §3 ADR-3): evita una galería con cero imágenes ante un fallo entre dos round-trips.';

-- ---------------------------------------------------------------------------
-- Function: set_contenido_imagenes (new — supabase/schemas/72_rpcs_contenidos.sql)
-- ---------------------------------------------------------------------------

create or replace function public.set_contenido_imagenes(
  p_contenido_id uuid,
  p_paths        text[]
)
returns table(removed_path text)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'no_autorizado' using errcode = '42501';
  end if;

  if p_paths is null or array_length(p_paths, 1) is null then
    raise exception 'galeria_vacia' using errcode = '23514';
  end if;

  if not exists (
    select 1
      from public.contenidos as c
     where c.id = p_contenido_id
       and c.tipo in ('cma', 'ic')
  ) then
    raise exception 'no_encontrado' using errcode = 'P0002';
  end if;

  return query
    with deleted as (
      delete from public.contenido_imagenes as ci
       where ci.contenido_id = p_contenido_id
         and ci.path <> all (p_paths)
      returning ci.path
    ),
    upserted as (
      insert into public.contenido_imagenes (contenido_id, path, orden)
      select p_contenido_id, p.path, p.ord
        from unnest(p_paths) with ordinality as p(path, ord)
      on conflict (contenido_id, orden) do update
        set path = excluded.path
      returning contenido_imagenes.contenido_id
    )
    select deleted.path from deleted;
end;
$$;

comment on function public.set_contenido_imagenes(uuid, text[]) is
  'Full-replace de las contenido_imagenes de una galería (cma/ic): borra las filas cuyo path ya no está en p_paths, re-inserta el resto con upsert sobre (contenido_id, orden) y devuelve los paths borrados (removed_path) para que el cliente purgue Storage best-effort. Valida is_admin(), p_paths no vacío y que el contenido exista y sea tipo cma/ic (no_encontrado si no).';

-- ---------------------------------------------------------------------------
-- Function: etapa_plan_completo (altered — supabase/schemas/71_rpcs_pacientes.sql)
-- ---------------------------------------------------------------------------

create or replace function public.etapa_plan_completo(p_etapa_id uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_total     integer;
  v_completas integer;
begin
  -- Total de semanas de contenido = cantidad_niveles * 4 (4 meses × 4 semanas).
  -- Fuente única (DEC-0-2): semanas_de_etapa, que también consume
  -- frases_de_etapa. cantidad_sesiones (16/32) es metadata clínica del equipo
  -- del equipo terapéutico, NO define las semanas de contenido.
  v_total := public.semanas_de_etapa(p_etapa_id);

  if v_total is null then
    return false;
  end if;

  -- Una semana (dia_offset / 7) está completa si tiene las 5 entregas
  -- persistibles: orden 1 (video), 2 (mantra), 3 (egregor), 4 (cma), 5 (ic) —
  -- el mismo invariante de 5 slots que enforce el front (isSemanaCompleta en
  -- semanaCompleteness.ts, SLOT_DEFINITIONS en slotDefinitions.ts). La frase
  -- (auto-derivada) quedó fuera del contrato de set_entregas_plan y nunca
  -- ocupa un orden de este rango. Filtramos a (1..5) explícitamente para que
  -- filas fuera de rango que sobrevivan de planes viejos ni cuenten a favor
  -- ni rompan la cuenta.
  select count(*)
    into v_completas
    from (
      select ep.dia_offset / 7 as semana
        from public.entregas_plan as ep
       where ep.etapa_id = p_etapa_id
         and ep.orden in (1, 2, 3, 4, 5)
       group by ep.dia_offset / 7
      having count(distinct ep.orden) = 5
    ) as t;

  return v_completas = v_total;
end;
$$;

comment on function public.etapa_plan_completo(uuid) is
  'Verifica si el plan de entregas de una etapa está completo: todas las semanas (semanas_de_etapa) tienen los 5 slots persistibles (órdenes 1=video, 2=mantra/audio, 3=egregor, 4=cma, 5=ic). La frase es derivada/automática y no participa de la completitud. Espeja la regla de completitud del front (isSemanaCompleta en semanaCompleteness.ts) y el mapa de slots (SLOT_DEFINITIONS en slotDefinitions.ts). Privada: la invoca set_entregas_plan.';

-- ---------------------------------------------------------------------------
-- Function: set_entregas_plan (altered — supabase/schemas/71_rpcs_pacientes.sql)
-- ---------------------------------------------------------------------------

create or replace function public.set_entregas_plan(
  p_etapa_id      uuid,
  p_entregas_plan jsonb default '[]'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_terapeuta_id  uuid;
  v_paciente_id   uuid;
  v_estado_activa uuid;
  v_arrancada     integer;
begin
  -- 1. Resolver la etapa y obtener el terapeuta dueño.
  select e.terapeuta_id into v_terapeuta_id
    from public.etapas_tratamiento as e
   where e.id = p_etapa_id;

  if not found then
    raise exception 'etapa_inexistente' using errcode = 'P0002';
  end if;

  -- 2. Verificar autorización: terapeuta dueño o admin.
  if not (public.is_admin() or auth.uid() = v_terapeuta_id) then
    raise exception 'no_autorizado' using errcode = '42501';
  end if;

  -- 3. Validación tipo-por-orden (DEC-8). El mapa de slots debe espejar
  --    SLOT_DEFINITIONS en app/controllers/Tratamiento/utils/slotDefinitions.ts
  --    y public.etapa_plan_completo (71_rpcs_pacientes.sql). Corre ANTES del
  --    delete: plpgsql hace rollback igual ante una excepción, pero fallar acá
  --    primero evita que el plan guardado del terapeuta desaparezca aunque
  --    sea momentáneamente, y cuesta un solo query en vez de
  --    delete + insert + rollback. El `case` no tiene `else`: un orden fuera
  --    de 1..5 da null, y `is distinct from` hace que null-vs-cualquier-cosa
  --    sea true → también lanza. Slots desconocidos se rechazan, no se
  --    ignoran.
  if exists (
    select 1
      from jsonb_array_elements(p_entregas_plan) as item
      join public.contenidos as c
        on c.id = nullif(item ->> 'contenido_id', '')::uuid
     where c.tipo is distinct from (
             case (item ->> 'orden')::int
               when 1 then 'video'
               when 2 then 'audio'
               when 3 then 'egregor'
               when 4 then 'cma'
               when 5 then 'ic'
             end
           )
  ) then
    raise exception 'tipo_slot_invalido' using errcode = '23514';
  end if;

  -- 4. Full-replace: borrar entregas actuales e insertar las nuevas.
  --    Todo ocurre en la transacción implícita de la función → atómico.
  delete from public.entregas_plan
   where etapa_id = p_etapa_id;

  insert into public.entregas_plan (etapa_id, dia_offset, contenido_id, orden)
  select
    p_etapa_id,
    ((item ->> 'semana')::int - 1) * 7,
    nullif(item ->> 'contenido_id', '')::uuid,
    (item ->> 'orden')::int
  from jsonb_array_elements(p_entregas_plan) as item;
  -- contenido_id not null valida cada fila; un item sin contenido_id
  -- aborta la transacción entera.

  -- 5. Si el plan quedó completo para todas las semanas (DEC-E1-2), devolver el
  --    paciente_id para que el web console dispare la emisión+entrega del OTP de
  --    activación vía la Edge Function paciente-invitacion. La emisión ya NO ocurre
  --    acá: Postgres no puede llamar a la Meta Cloud API y el plaintext del OTP debe
  --    entregarse por WhatsApp desde un boundary de Edge Function (DevSpec §9.2).
  --    La idempotencia (no duplicar OTP) la garantiza generar_otp_activacion en la EF.
  if public.etapa_plan_completo(p_etapa_id) then
    -- 1. Arranque: idempotente (fecha_inicio is null) e irreversible.
    --    fecha_finalizacion is null: NO se resucita una etapa cerrada (DEC-E1-2).
    select ee.id into v_estado_activa
      from public.estados_etapa as ee
     where ee.codigo = 'activa';

    update public.etapas_tratamiento
       set fecha_inicio = current_date,
           estado_id    = v_estado_activa
     where id = p_etapa_id
       and fecha_inicio is null
       and fecha_finalizacion is null;

    get diagnostics v_arrancada = row_count;

    -- 2. Recompute de la agenda: SOLO si arrancó recién (DEC-4).
    if v_arrancada = 1 then
      update public.niveles as n
         set fecha_seguimiento_esperada =
               (current_date + (n.numero_nivel * interval '1 month'))::date
       where n.etapa_id = p_etapa_id;
    end if;

    -- 3. Devolver el paciente_id (comportamiento EXISTENTE, no se toca — DEC-E1-1).
    select e.paciente_id into v_paciente_id
      from public.etapas_tratamiento as e
     where e.id = p_etapa_id;

    return v_paciente_id;
  end if;

  return null;
end;
$$;

comment on function public.set_entregas_plan(uuid, jsonb) is
  'Full-replace del plan de entregas de una etapa: valida primero el mapa tipo-por-orden (DEC-8: 1=video, 2=audio, 3=egregor, 4=cma, 5=ic — debe espejar SLOT_DEFINITIONS en slotDefinitions.ts; lanza tipo_slot_invalido, 23514, si no matchea, y no toca el plan guardado), luego borra las filas previas e inserta las del JSONB recibido. Si el plan queda completo (todas las semanas con sus 5 slots persistibles — via etapa_plan_completo; la frase dejó de ser una entrega asignable en frasesAutomaticas, se deriva de causa+algoritmo+semana), arranca el tratamiento de forma idempotente e irreversible (fecha_inicio = current_date, estado ''activa'', solo si fecha_inicio y fecha_finalizacion eran NULL — DEC-E1-2 evita resucitar una etapa cerrada) y, si arrancó recién, recomputa fecha_seguimiento_esperada de los niveles anclada al arranque real (DEC-4). Siempre que el plan está completo devuelve el paciente_id, arrancado o no, para que el web console dispare la emisión+entrega del OTP de activación (EF paciente-invitacion) — el reintento del OTP depende de este return no acoplarse al arranque (DEC-E1-1); en caso contrario devuelve null. Acceso: el terapeuta dueño de la etapa o un admin.';

-- ---------------------------------------------------------------------------
-- Function: get_mi_plan_semanal (altered — supabase/schemas/74_rpcs_mi_paciente.sql)
-- ---------------------------------------------------------------------------

create or replace function public.get_mi_plan_semanal()
returns jsonb
language plpgsql
security definer
stable
set search_path = ''
as $$
declare
  v_paciente_id uuid;
  v_etapa_id    uuid;
  v_fecha_inicio date;
  v_result      jsonb;
begin
  -- 1. Resolver identidad del paciente caller (lanza no_vinculado si no hay vínculo).
  v_paciente_id := public.get_mi_paciente_id();

  -- 2. Resolver la etapa activa (gate sin_etapa_activa).
  --    No se necesita la modalidad: las semanas salen de las entregas_plan realmente
  --    cargadas (el plan se autoriza completo antes de generar el OTP).
  select et.id, et.fecha_inicio
    into v_etapa_id, v_fecha_inicio
    from public.etapas_tratamiento as et
   where et.paciente_id = v_paciente_id
     and et.fecha_finalizacion is null
     and et.fecha_inicio is not null      -- ← una etapa sin arrancar NO es un tratamiento activo
   order by et.fecha_inicio desc, et.created_at desc
   limit 1;

  if not found then
    raise exception 'sin_etapa_activa' using errcode = 'P0001';
  end if;

  -- 3. Armar el array de semanas en un único query con CTEs (DEC-3-1…DEC-3-4).
  --    Una fila de salida por SEMANA (no por entrega): fechaDesbloqueo es el
  --    inicio de la semana (fecha_inicio + (semana-1)*7), robusto a entregas en
  --    días distintos dentro de la misma semana (evita semanas duplicadas).
  with base as (
    -- Una fila por entrega_plan: deriva semana y los campos de contenido.
    -- La frase ya NO sale de acá (Task 2.2): frase_id/frases_motivacionales
    -- fueron retirados de esta CTE; la lista de semanas sigue viniendo de
    -- entregas_plan (DEC-2-1), pero su contenido de frases se resuelve más
    -- abajo con la CTE frases_por_semana.
    select
      floor(ep.dia_offset / 7)::int + 1 as semana,
      ep.orden,
      ep.dia_offset,
      ep.contenido_id,
      c.id           as pieza_id,
      c.tipo         as pieza_tipo,
      c.titulo       as pieza_titulo,
      c.descripcion  as pieza_descripcion,
      c.recurso_ref  as pieza_recurso_ref,
      c.duracion_seg as pieza_duracion
    from public.entregas_plan as ep
    left join public.contenidos as c on c.id = ep.contenido_id
    where ep.etapa_id = v_etapa_id
  ),
  semanas as (
    -- Una fila por semana distinta; fecha_desbloqueo = inicio de la semana.
    select
      b.semana,
      (v_fecha_inicio + (b.semana - 1) * 7)::date as fecha_desbloqueo
    from base as b
    group by b.semana
  ),
  marcadas as (
    -- estadoSemana por semana. Ventana semiabierta [desbloqueo, desbloqueo+7).
    select
      s.semana,
      s.fecha_desbloqueo,
      case
        when current_date <  s.fecha_desbloqueo     then 'futura'
        when current_date >= s.fecha_desbloqueo + 7 then 'anterior'
        else 'actual'
      end as estado_semana
    from semanas as s
  ),
  frases_por_semana as (
    -- Frases derivadas de la etapa (Task 0.3, epic-0): 3 objetos por semana
    -- ya ordenados por orden. Joineada por semana contra `marcadas`, nunca
    -- agrega semanas nuevas (frases_de_etapa puede cubrir más semanas que
    -- las que tienen media cargada; el join en el select final filtra eso).
    select
      f.semana,
      jsonb_agg(
        jsonb_build_object(
          'orden',  f.orden,
          'origen', f.origen,
          'texto',  f.texto
        )
        order by f.orden
      ) as frases
    from public.frases_de_etapa(v_etapa_id) as f
    group by f.semana
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'semana',          m.semana,
      'estadoSemana',    m.estado_semana,
      'fechaDesbloqueo', m.fecha_desbloqueo,
      -- piezas: filas de media (contenido_id not null) de la semana, ordenadas
      -- por (orden, dia_offset). recursoRef E imagenes nuleados server-side
      -- para futuras, en el MISMO case cada uno (design §6 ADR-5): ambos
      -- keys leen el mismo m.estado_semana en el mismo scope, y el case de
      -- imagenes corta en corto en 'futura' — el subquery a
      -- contenido_imagenes directamente NO SE EVALÚA para una semana futura,
      -- los paths no solo se descartan, nunca se leen. No repetir el error de
      -- separar esta regla en un case/CTE distinto (así casi se pierde
      -- `frases`, ver DEC-9). Semana sin media devuelve piezas: [] (coalesce).
      'piezas', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id',          b.pieza_id,
            'tipo',        b.pieza_tipo,
            'titulo',      b.pieza_titulo,
            'descripcion', b.pieza_descripcion,
            'recursoRef',  case when m.estado_semana = 'futura' then null else b.pieza_recurso_ref end,
            'imagenes',    case
                              when m.estado_semana = 'futura' then '[]'::jsonb
                              else coalesce((
                                select jsonb_agg(
                                         jsonb_build_object('path', ci.path, 'orden', ci.orden)
                                         order by ci.orden)
                                  from public.contenido_imagenes as ci
                                 where ci.contenido_id = b.pieza_id
                              ), '[]'::jsonb)
                            end,
            'duracion',    b.pieza_duracion
          )
          order by b.orden, b.dia_offset
        )
        from base as b
        where b.semana = m.semana
          and b.contenido_id is not null
      ), '[]'::jsonb),
      -- frases: los 3 objetos { orden, origen, texto } derivados de
      -- frases_de_etapa para esta semana, ya ordenados por orden. Nuleada
      -- (vaciada) server-side para semanas futuras (DEC-2-2, misma regla que
      -- ya se aplica a recursoRef). Sin fila en frases_por_semana (run-out
      -- del catálogo) → [] via coalesce, nunca null.
      'frases', case
        when m.estado_semana = 'futura' then '[]'::jsonb
        else coalesce(fps.frases, '[]'::jsonb)
      end
    )
    order by m.semana
  ), '[]'::jsonb)
  into v_result
  from marcadas as m
  left join frases_por_semana as fps on fps.semana = m.semana;

  return v_result;
end;
$$;

comment on function public.get_mi_plan_semanal() is
  'Devuelve el plan de tratamiento semanal del paciente caller como array jsonb. '
  'Cada elemento: { semana, estadoSemana, fechaDesbloqueo, piezas: [{ id, tipo, titulo, descripcion, recursoRef, imagenes: [{path, orden}], duracion }], frases: [{ orden, origen, texto }] }. '
  'semana = floor(dia_offset/7)+1; fechaDesbloqueo = fecha_inicio + dia_offset. '
  'estadoSemana: futura (hoy < desbloqueo), actual ([desbloqueo, desbloqueo+7)), anterior (hoy >= desbloqueo+7). '
  'La lista de semanas sigue viniendo de entregas_plan (una semana existe si tiene media cargada); '
  'frases se deriva invocando public.frases_de_etapa(v_etapa_id) (Task 0.3) y se joinea por semana, '
  'nunca agrega semanas nuevas. frases trae hasta 3 objetos ordenados por orden; [] si la semana no tiene '
  'frases derivadas (run-out del catálogo) o si es futura (DEC-2-2, misma nulling que recursoRef). '
  'imagenes trae el array ordenado {path, orden} de contenido_imagenes para piezas tipo galería (cma/ic); '
  '[] para toda pieza no-galería (no hay filas). '
  'El campo escalar frase (deprecado) NO existe en este contrato: no se lee entregas_plan.frase_id ni frases_motivacionales. '
  'Nulling de futuras: recursoRef por pieza = null e imagenes = [] (subquery nunca evaluado) y frases = [] cuando estadoSemana = futura — NO NEGOCIABLE, evita filtrar paths de bucket de semanas no desbloqueadas. '
  'recursoRef e imagenes[].path son paths del bucket, NO URLs firmadas — el mobile firma client-side. '
  'Etapa sin entregas → []. Lanza sin_etapa_activa (P0001) si no hay etapa activa o si la única etapa existe '
  'pero no arrancó (fecha_inicio null — Task 5.1); no_vinculado (P0001) si no hay vínculo.';
